import React from 'react';

// Cette barre de navigation s'affiche en haut de l'écran, une fois connecté.
// Elle permet de changer de "page" en appelant onNaviguer (défini dans App.js).
function Navbar({ user, onNaviguer, onDeconnexion }) {
    return (
        <nav className="navbar navbar-dark bg-dark mb-4">
            <div className="container">
                <span className="navbar-brand">GCT - Signature Électronique</span>

                <div>
                    <button className="btn btn-outline-light btn-sm me-2" onClick={() => onNaviguer('liste')}>
                        Liste des documents
                    </button>

                    {/* Seul l'employé a le droit de créer un nouveau document */}
                    {user.role === 'employe' && (
                        <button className="btn btn-outline-light btn-sm me-2" onClick={() => onNaviguer('creer')}>
                            Nouveau document
                        </button>
                    )}

                    <button className="btn btn-outline-light btn-sm me-2" onClick={() => onNaviguer('historique')}>
                        Historique des signatures
                    </button>

                    <span className="text-white me-2">
                        {user.prenom} {user.nom} ({user.role})
                    </span>

                    <button className="btn btn-outline-warning btn-sm" onClick={onDeconnexion}>
                        Déconnexion
                    </button>
                </div>
            </div>
        </nav>
    );
}

export default Navbar;
